package com.ecommerce.cart.security;
import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt; public JwtFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{String id=jwt.userId(h.substring(7).trim());SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id,null,List.of(new SimpleGrantedAuthority("ROLE_USER"))));}catch(JwtException|IllegalArgumentException e){SecurityContextHolder.clearContext();s.setStatus(401);s.setContentType("application/json");s.getWriter().write("{\"error\":\"Invalid or expired token\"}");return;}}c.doFilter(r,s);}}